def test_init_shape_castable_const(self):
    class CastableFromHex(ShapeCastable):
        def as_shape(self):
            return unsigned(8)

        def __call__(self, value):
            return value

        def const(self, init):
            return int(init, 16)

        def from_bits(self, bits):
            return bits

    s1 = Signal(CastableFromHex(), init="aa")
    self.assertEqual(s1.init, 0xaa)
